  store.numbers.delete(key)
}

// The next number for a user's new note: one past the highest they have ever had.
export const nextNumber = (store: NoteStore, key: string) => {
  const number = (store.numbers.get(key) ?? 0) + 1
  store.numbers.set(key, number)
  return number
}
})

